/**
 * src/world/portedDefs.ts — catalogue + per-family recipes for the 48 PORTED original tracks
 * (src/world/ports/*, generated by research/tools/port_tracks.py).
 *
 * Ported exactly (PROGRESS.md rules): centre line, elevation, widths, cross-fall, checkpoints
 * (race event triggers), spawn grid, valid range, default tyre, laps — per data module.
 * Procedural & neutral around the real road: terrain drape, scenery, surface-section layout
 * (the per-stage material SHARES are the original's, spec §4.3.1), environment palettes.
 *
 * Families (original stage groups, spec §4.3.1):
 *   corsica     tarmac rally (asphalt 96 %; stage 2 + gravel 14.4 %)
 *   kenya       safari desert rally (sand 98.7 / 82.0 / 53.6 %, asphalt 17.8 / 24.1 %,
 *               gravel 22.3 % on stage 3)
 *   newzealand  forest rally (mud 98-100 %; stage 2 + grass 1.7 %)
 *   hillclimb   gravel climbs 1-2 (gravel 87-100 %) / snow climbs 3 (SNOWASPHALT 100 %)
 *   iceracing    frozen-lake laps (ICEASPHALT 97-100 %)
 *   rallycross   circuit laps (GRAVEL 62.5 % / ASPHALT 37.5 %)
 */
import { MATERIAL } from '../core/constants';
import type { Corner } from './corners';
import { chevronRotY, type KindSpec, type SceneryPlacer } from './scenery';
import { PORTED_DATA, PORTED_ORDER } from './ports';
import type { PortedFamily, PortedRecipe, SurfaceMix } from './portedBuilder';
import type { StageMeta } from './builder';
import type { StageListEntry } from '../core/types';

const DEG = Math.PI / 180;

/** What every family scenery script gets (one analyzeCorners pass, shared with the pacenotes). */
export interface PortedSceneryCtx {
  readonly cl: import('./centerline').Centerline;
  readonly corners: readonly Corner[];
  readonly startS: number;
  readonly finishS: number;
  readonly closed: boolean;
  readonly rng: import('../core/rng').Rng;
}

// ------------------------------------------------------------------------------------------- shared scenery

function portFurniture(p: SceneryPlacer, ctx: PortedSceneryCtx, crowd: boolean): void {
  const { startS, finishS } = ctx;
  for (const side of [-1, 1]) {
    p.line({ kind: 'banner', from: startS - 28, to: ctx.closed ? startS + 620 : startS - 4, every: 9, e: 2.4, side, height: 2.4, along: true });
    if (!ctx.closed) p.line({ kind: 'banner', from: finishS - 20, to: finishS + 14, every: 9, e: 2.4, side, height: 2.4, along: true });
  }
  if (crowd) {
    p.crowd(startS + 10, -1, 7, 8, 12);
    if (!ctx.closed) p.crowd(finishS + 6, 1, 7, 8, 12);
  }
}

/** Chevron boards on the outside and don't-cut rocks on the inside of the real corners. */
function cornerFurniture(p: SceneryPlacer, ctx: PortedSceneryCtx, rockChance: number): void {
  const { rng, cl, corners } = ctx;
  for (const c of corners) {
    if (!ctx.closed && (c.s0 < ctx.startS + 10 || c.s1 > ctx.finishS - 10)) continue;
    if (c.hairpin || c.severity <= 2) {
      for (const k of [-9, 0, 9]) {
        const pt = p.sidePoint(c.apexS + k, -c.dir, 4.4);
        p.tryPlace('marker', pt.x, pt.z, 0.12, 1.5, chevronRotY(pt.hx, pt.hz, c.dir), { clear: 3, spacing: 0.2 });
      }
    }
    if (!c.hairpin && c.severity >= 3 && c.severity <= 5 && c.angle > 30 * DEG && rng.next() < rockChance) {
      let placed = 0;
      for (const k of [-10, -3, 5]) {
        const r = rng.range(0.6, 0.95);
        const pt = p.sidePoint(c.apexS + k + rng.range(-2, 2), c.dir, 3.2 + r + rng.range(0, 1.2));
        if (p.tryPlace('rock', pt.x, pt.z, r, rng.range(0.6, 1.0), rng.next() * 6.28, { clear: 3, spacing: 0.3 })) placed++;
      }
      if (placed > 0) (c as { dontCut: boolean }).dontCut = true;
    }
  }
  void cl;
}

/** White marker posts along the stage edges. */
function posts(p: SceneryPlacer, ctx: PortedSceneryCtx, every: number, e: number): void {
  p.line({ kind: 'post', from: 0, to: ctx.cl.length, every, e, side: 'alternate', radius: 0, height: 1.2, jitter: 1.5, clear: 2.4 });
}

// ------------------------------------------------------------------------------------------- families

const CORSICA: PortedFamily = {
  env: 'corsica',
  mix: {
    1: { base: 'tarmac', accents: [{ surface: 'gravel', share: 0.035 }] },
    2: { base: 'tarmac', accents: [{ surface: 'gravel', share: 0.14 }] },
  } as unknown as Readonly<Record<string, SurfaceMix>>,
  mixDefault: { base: 'tarmac', accents: [{ surface: 'gravel', share: 0.08 }] },
  terrain: { amp: 16, big: 620, small: 130 },
  carve: () => ({ cutSlope: 1.35, fillSlope: 1.2, ditchDepth: 0.7, ditchWidth: 3, ditchStart: 2.5, rInf: 14, underDepth: 0.3 }),
  crown: (s) => (s === 'tarmac' || s === 'water' ? 0.03 : 0.015), // ASPHALT / WATERASPHALT
  groundMat: (c, n) => {
    if (c.e < 0) return c.roadMat;
    if (c.slope > 0.62) return MATERIAL.gravel;
    if (n.perlin(c.x / 40, c.z / 40) > 0.25) return MATERIAL.gravel;
    return MATERIAL.grass;
  },
  scenery: (p, ctx) => {
    portFurniture(p, ctx, true);
    cornerFurniture(p, ctx, 0.25);
    posts(p, ctx, 60, 3.5);
    p.scatter({
      kinds: [
        { kind: 'pine', w: 4, radius: [0.32, 0.5], height: [9, 18] },
        { kind: 'bush', w: 2.2, radius: [0, 0], height: [0.8, 1.6] },
        { kind: 'rock', w: 1.2, radius: [0.5, 1.1], height: [0.6, 1.4] },
      ] as KindSpec[],
      density: 2.2, band: [10, 70], outer: 0.5, spacing: 3, clear: 3.2,
    });
  },
};

