function familyOf(archive: string): PortedFamily {
  if (/^hillclimb3/.test(archive)) return HILLCLIMB_SNOW;
  if (/^hillclimb/.test(archive)) return HILLCLIMB;
  if (/^corsica/.test(archive)) return CORSICA;
  if (/^iceracing/.test(archive)) return ICERACING;
  if (/^kenya/.test(archive)) return KENYA;
  if (/^newzealand/.test(archive)) return NEWZEALAND;
  if (/^rallycross/.test(archive)) return RALLYCROSS;
  throw new Error(`no ported family for archive '${archive}'`);
}

// ------------------------------------------------------------------------------------------- catalogue

const DIR_WORD = { f: 'Forward', r: 'Reverse' } as const;
const FAMILY_LABEL: Readonly<Record<string, string>> = Object.freeze({
  corsica: 'Corsica',
  hillclimb: 'Hillclimb',
  iceracing: 'Ice Racing',
  kenya: 'Kenya',
  newzealand: 'New Zealand',
  rallycross: 'Rallycross',
});
const FAMILY_DISCIPLINE: Readonly<Record<string, StageMeta['discipline']>> = Object.freeze({
  corsica: 'rally',
  hillclimb: 'hillclimb',
  iceracing: 'ice',
  kenya: 'rally',
  newzealand: 'rally',
  rallycross: 'rallycross',
});
const FAMILY_BLURB: Readonly<Record<string, string>> = Object.freeze({
  corsica: 'Mediterranean mountain tarmac: fast flowing cliffside road with real crests and hairpins.',
  hillclimb: 'A real mountain hillclimb: narrow road cut into the steep hillside, big elevation gain.',
  iceracing: 'Studded laps around a frozen lake: wide swept ice corners between snowbanks.',
  kenya: 'The classic safari rally: wide, fast sandy tracks with tarmac and gravel passages.',
  newzealand: 'Narrow muddy forestry roads over rolling country: trees close,surface loose.',
  rallycross: 'A closed rallycross circuit: wide gravel and tarmac, barriers close, laps against the clock.',
});

function portedMeta(id: string): StageMeta {
  const data = PORTED_DATA[id];
  const fam = familyOf(data.archive);
  const m = /^(corsica|hillclimb|iceracing|kenya|newzealand|rallycross)(\d+[a-c]?)([fr])\.rff$/.exec(data.archive);
  if (!m) throw new Error(`unparsed archive '${data.archive}'`);
  const [, famKey, num, dir] = m;
  const sub = famKey === 'hillclimb' ? num.toUpperCase() : num;
  const timed = data.triggers[data.triggers.length - 1] - data.triggers[0];
  return {
    id,
    name: `${FAMILY_LABEL[famKey]} ${sub} (${DIR_WORD[dir as 'f' | 'r']})`,
    discipline: FAMILY_DISCIPLINE[famKey],
    closed: data.closed,
    laps: data.laps,
    defaultTyre: data.defaultTyre,
    approxLength: Math.round(data.closed ? data.splineLength : timed),
    env: fam.env,
    description: `${FAMILY_BLURB[famKey]} Ported centre line, checkpoints and timing of the original stage (research reference ${data.archive}).`,
  };
}

/** META entries of the ported stages (id → StageMeta). */
export const PORTED_META: Readonly<Record<string, StageMeta>> = Object.freeze(
  Object.fromEntries(PORTED_ORDER.map((id) => [id, portedMeta(id)])),
) as Readonly<Record<string, StageMeta>>;

/** Catalogue entries of the ported stages, in PORTED_ORDER (original event order). */
export function portedCatalogue(): StageListEntry[] {
  return PORTED_ORDER.map((id) => {
    const m = PORTED_META[id];
    return {
      id: m.id,
      name: m.name,
      discipline: m.discipline,
      description: m.description,
      defaultTyre: m.defaultTyre,
      approxLength: m.approxLength,
      closed: m.closed,
      laps: m.laps,
    };
  });
}

/** Recipes for the ported stages (id → () => PortedRecipe). */
export const PORTED_RECIPES: Readonly<Record<string, () => PortedRecipe>> = Object.freeze(
  Object.fromEntries(
    PORTED_ORDER.map((id) => [
      id,
      (): PortedRecipe => ({ meta: PORTED_META[id], data: PORTED_DATA[id], family: familyOf(PORTED_DATA[id].archive) }),
    ]),
  ),
) as Readonly<Record<string, () => PortedRecipe>>;

export { PORTED_ORDER };
export type { PortedFamily, PortedRecipe, SurfaceMix };